import java.io.*;
import java.util.*;

public class CF_884F {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        char[] s = br.readLine().trim().toCharArray();
        String[] tokens = br.readLine().trim().split("\\s");
        int[] beauty = new int[n];
        int totalBeauty = 0;
        for (int i = 0; i < n; i++) {
            beauty[i] = Integer.parseInt(tokens[i]);
            totalBeauty += beauty[i];
        }
        int t = 0;
        int[] countChars = new int[26];
        int minSum = 0;
        for (int i = 0; i < n / 2; i++) {
            if (s[i] == s[n - i - 1]) {
                t++;
                countChars[s[i] - 'a']++;
                minSum += Math.min(beauty[i], beauty[n - i - 1]);
            }
        }
        int maxCount = 0;
        int maxCharIndex = 0;
        for (int i = 0; i < 26; i++) {
            if (countChars[i] > maxCount) {
                maxCount = countChars[i];
                maxCharIndex = i;
            }
        }
        if (2 * maxCount <= t) {
            System.out.println(totalBeauty);
            return;
        }
        List<Integer> removable = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            if ((s[i] - 'a') != maxCharIndex && (s[n - i - 1] - 'a') != maxCharIndex && s[i] != s[n - i - 1]) {
                removable.add(Math.min(beauty[i], beauty[n - i - 1]));
            }
        }
        Collections.sort(removable);
        int toRemove = 2 * maxCount - t;
        for (int i = 0; i < toRemove; i++) {
            totalBeauty -= removable.get(i);
        }
        System.out.println(totalBeauty);
    }
}
